-- Analysis build of the supplied original. Not the reconstructed source.
-- Records only function IDs, program counters, opcodes, and numeric operands.
-- Output: andromeda_vm_trace.txt, written with GameSense writefile.
-- Run this file separately from andromeda.lua. The trace is created immediately.
local __andromeda_ids={}
local __andromeda_seen_records={}
local __andromeda_records={"ANDROMEDA_VM_TRACE_V1"}
local __andromeda_watched={f1=true,f45=true,f108=true,f115=true,f416=true}
local __andromeda_flushing=false
local __andromeda_path="andromeda_vm_trace.txt"
local __andromeda_last_notice
local function __andromeda_notice(message)
    if message==__andromeda_last_notice then return end
    __andromeda_last_notice=message
    local logger=type(client)=="table" and client.log or print
    if type(logger)=="function" then pcall(logger,"[Andromeda trace] "..message) end
end
local function __andromeda_flush()
    if __andromeda_flushing then return false end
    if type(writefile)~="function" then
        __andromeda_notice("NOT SAVED: GameSense writefile is unavailable")
        return false
    end
    local contents=table.concat(__andromeda_records,"\n").."\n"
    __andromeda_flushing=true
    local ok,result=pcall(writefile,__andromeda_path,contents)
    __andromeda_flushing=false
    if not ok or result==false then
        __andromeda_notice("NOT SAVED: "..tostring(result))
        return false
    end
    if type(readfile)=="function" then
        local read_ok,saved=pcall(readfile,__andromeda_path)
        if not read_ok or saved~=contents then
            __andromeda_notice("NOT VERIFIED: cannot read back "..__andromeda_path)
            return false
        end
        __andromeda_notice("SAVED AND VERIFIED: "..__andromeda_path.." (relative to the csgo folder)")
    else
        __andromeda_notice("WRITE COMPLETED: "..__andromeda_path.." (readfile unavailable; not verified)")
    end
    return true
end
local function __andromeda_register(root)
    local seen={}
    local count=0
    local function visit(t)
        if type(t)~="table" or seen[t] then return end
        seen[t]=true
        if rawget(t,7)~=nil and type(rawget(t,4))=="table" and
            type(rawget(t,8))=="table" and (rawget(t,9)==0 or rawget(t,9)==1) then
            count=count+1
            __andromeda_ids[t]="f"..count
        end
        local keys={}
        for k in next,t do keys[#keys+1]=k end
        table.sort(keys,function(a,b)
            if type(a)==type(b) then return a<b end
            return type(a)<type(b)
        end)
        for _,k in ipairs(keys) do visit(rawget(t,k)) end
    end
    visit(root)
    __andromeda_records[#__andromeda_records+1]="FUNCTIONS "..count
    __andromeda_flush()
end
local function __andromeda_trace(proto,pc,opcode)
    local id=__andromeda_ids[proto]
    if not id then return end
    if id=="f2" then
        __andromeda_records[#__andromeda_records+1]="ENVIRONMENT_CHECK_REJECTED"
        local saved=__andromeda_flush()
        error("ANDROMEDA_TRACE_ENVIRONMENT_CHECK_FAILED; "..
            (saved and "trace saved" or "trace NOT saved; see console"),0)
    end
    if not __andromeda_watched[id] then return end
    local fields={id,tostring(pc),tostring(opcode)}
    for _,slot in ipairs({2,6,11,1,3,10}) do
        local operands=rawget(proto,slot)
        local v=type(operands)=="table" and rawget(operands,pc) or nil
        fields[#fields+1]=type(v)=="number" and tostring(v) or "_"
    end
    local row=table.concat(fields," ")
    if __andromeda_seen_records[row] then return end
    if #__andromeda_records>=50000 then return end
    __andromeda_seen_records[row]=true
    __andromeda_records[#__andromeda_records+1]=row
    if #__andromeda_records%64==0 then __andromeda_flush() end
end
__andromeda_flush()
if type(client)=="table" then
    if type(client.delay_call)=="function" then
        client.delay_call(3,__andromeda_flush)
        client.delay_call(15,__andromeda_flush)
    end
    if type(client.set_event_callback)=="function" then
        client.set_event_callback("shutdown",__andromeda_flush)
    end
end
